<script lang="ts">
  import { Accordion } from 'bits-ui';
  import { CaretDown } from 'phosphor-svelte';
  import { tokenText } from './model';
  import type { Bundle } from './model';
  let { bundle }: { bundle: Bundle } = $props();
  const c = $derived(bundle.comparison);
  const recordedSource = $derived(bundle.scenario?.source);
</script>
<section id="responses" class="response-section" aria-label="Recorded responses">
  <div class="section-heading"><div><span class="eyebrow">BEHAVIOUR ALONGSIDE THE READOUT</span><h2>{bundle.mode === 'matched' ? 'The fixed reference text' : 'Two recorded continuations'}</h2></div></div>
  {#if bundle.mode === 'matched'}
    <p class="section-description">Both arms consumed {recordedSource?'the recorded source sequence':'the baseline sequence'} below. This is <strong>not</strong> a response generated by the steered arm. {recordedSource?'For new answers, open the separate answer scenario with the same source episode.':'Switch to Free generation to read its own response.'}</p>
    <article class="response-card"><header><span class="arm-dot"></span><h3>{recordedSource?'Recorded source reference':'Baseline reference'}</h3><span class="mono">FIXED INPUT</span></header><p class="response-text">{bundle.text.baseline.answer || 'No answer text in this export.'}</p>{@render reasoning(bundle.text.baseline.reasoning,'baseline-reference')}</article>
  {:else}
    <p class="section-description">{recordedSource?'The recorded thinking was prefilled, then each arm generated its own answer. The historical source label does not classify these answers.':'Each arm generated its own text.'} A shared position number does not make different histories comparable.</p>
    {#if c.divergence}
      <div class="divergence-callout" data-testid="divergence"><span class="divergence-symbol" aria-hidden="true">⑂</span><div><strong>Histories split at position {c.divergence.position}</strong><p>Baseline: <code>{c.divergence.baseline_token === null ? 'Ended' : tokenText(bundle.vocab,c.divergence.baseline_token)}</code> · Steered: <code>{c.divergence.steered_token === null ? 'Ended' : tokenText(bundle.vocab,c.divergence.steered_token)}</code>. Paired readouts end at {c.divergence.position-1}. No post-divergence difference is shown.</p></div></div>
    {:else}<p class="method-note">No token divergence is recorded in this comparison.</p>{/if}
    <div class="response-pair">
      {#each ['baseline','steered'] as side}
        {@const key=side as 'baseline'|'steered'}
        <article class="response-card {side}"><header><span class="arm-dot"></span><h3>{side==='baseline'?'Baseline':'Steered'}</h3><span class="mono">OWN GENERATION</span></header><p class="response-text">{bundle.text[key].answer || 'No answer text in this export.'}</p>{@render reasoning(bundle.text[key].reasoning,side)}
          {#if c.divergence && c.tracks}<details class="track"><summary>Independent token track after the split · {c.tracks[key].length} tokens</summary><p class="track-note">Token text only. This bundle does not supply post-divergence paired states.</p><div class="track-tokens" aria-label={`${side} independent token track`}>{#each c.tracks[key] as id, i}<span title={`Own position ${c.divergence.position+i}; token ${id}`}>{tokenText(bundle.vocab,id)}</span>{/each}</div></details>{/if}
        </article>
      {/each}
    </div>
  {/if}
  <p class="footnote">Text is shown in full as exported, without interpretation or HTML execution. {recordedSource?'Only stepped reasoning/answer text is exported; prefilled thinking is not included in this text panel. ':''}The export has no stop-reason field; a recorded response may end at its token budget.</p>
</section>
{#snippet reasoning(text:string,key:string)}
  <Accordion.Root type="single"><Accordion.Item value={key}><Accordion.Header><Accordion.Trigger class="flex w-full items-center justify-between gap-3 border-t border-[#30363e] py-3 text-left text-xs text-[#aab2bf]">Recorded reasoning / envelope text<CaretDown size={14}/></Accordion.Trigger></Accordion.Header><Accordion.Content><pre class="reasoning-text">{text || 'No reasoning text in this export.'}</pre></Accordion.Content></Accordion.Item></Accordion.Root>
{/snippet}
